Here is the commit message:
ui: fix ncurses errors

Fix NCURSES errors introduced in commit 94f8626 (main: split struct
target into main/module parts).

Here is the root cause:
The bug was caused by incorrect escape sequences in the `fprintf` function calls for terminal output, which were introduced in a previous commit that altered the structure of the code. This led to NCURSES errors when attempting to format and display text in the terminal, particularly when handling color codes and output for network targets.

Here is the patch:
  */
 void
 termio_cleanup(void)
 {
 #ifndef NCURSES
 	setvbuf(stdout, NULL, _IONBF, 0);
 	if (scrbuffer)
 		free(scrbuffer);
 	if (isatty(STDIN_FILENO))
 		tcsetattr(STDIN_FILENO, TCSAFLUSH, &oterm); // XXX: TCASOFT? see openssh
 #else /* NCURSES */
 	struct target *t;
 	int col, i;
 	int imax, ifirst, ilast;

 	t = list;
 	if (t == NULL)
 		return;

 	col = getmaxx(stdscr);
 	imax = MIN(t->npkts, col - labelwidth);
 	imax = MIN(imax, NUM);
 	ifirst = (t->npkts > imax ? t->npkts - imax : 0);
 	ilast = t->npkts;

 	endwin();
 	DL_FOREACH(list, t) {
 		if (C_flag && t->af == AF_INET6)
 			fprintf(stdout, "%c[2;32m%*.*s%c[0m",
 			    0x1b, w_width, w_width, t->host, 0x1b);
 		else if (C_flag && t->af == AF_INET)
-			fprintf(stdout, "%c[2;31m%*.*%sc[0m",
+			fprintf(stdout, "%c[2;31m%*.*s%c[0m",
 			    0x1b, w_width, w_width, t->host, 0x1b);
 		else
 			fprintf(stdout, "%*.*s", w_width, w_width, t->host);
 		if (w_width)
 			fputc(' ', stdout);
-		if (t->duplicate != NULL)
-			fprintf(stdout, "(duplicate of %s)", t->duplicate->host);
-		else {
-			for (i=ifirst; i<ilast; i++) {
-				if (i < t->npkts)
-					fputc(t->res[i % NUM], stdout);
-				else
-					fputc(' ', stdout);
-			}
+		for (i=ifirst; i<ilast; i++) {
+			if (i < t->npkts)
+				fputc(t->res[i % NUM], stdout);
+			else
+				fputc(' ', stdout);
 		}
 		fputc('\n', stdout);
 	}
 #endif /* !NCURSES */
 }
